// ─── File: StatelessScalingDemo.java ───
// Shows: local-state breakage + Redis/JWT fix; round robin vs least connections;
// readiness health checks that verify an instance can actually SERVE.
import java.util.*;
import java.util.logging.*;

public class StatelessScalingDemo {
    private static final Logger log = Logger.getLogger("Scale");
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AppInstance a = new AppInstance("app-A");
        AppInstance b = new AppInstance("app-B");
        AppInstance c = new AppInstance("app-C");
        List<AppInstance> pool = new ArrayList<>(List.of(a, b, c));
        SharedSessionStore redis = new SharedSessionStore();

        // PROBLEM 1: local state. A creates a LOCAL session; B cannot see it.
        log.info("=== local-state breakage ===");
        a.localLogin("SAV2001");                       // stored in A's memory only
        log.warning(() -> "B sees local session for SAV2001? " + b.hasLocalSession("SAV2001"));

        // FIX: externalize to Redis — any instance can read it.
        log.info("=== fix: externalize session to Redis ===");
        redis.put("SAV2001", "{\"customer\":\"SAV2001\"}");
        log.info(() -> "B reads SAV2001 session from Redis: " + (redis.get("SAV2001") != null));

        // PROBLEM 2: round robin balances count, not work.
        log.info("=== round robin: equal count, UNEQUAL work ===");
        a.addWorkMillis(2000); a.addWorkMillis(2000);  // A got two slow requests
        b.addWorkMillis(5); c.addWorkMillis(5);        // B,C got fast ones
        log.warning(() -> "A load=" + a.loadMillis() + "ms, B=" + b.loadMillis()
                + "ms, C=" + c.loadMillis() + "ms — same count, lopsided work");

        // FIX: least connections routes to the least-busy instance.
        log.info("=== fix: least connections ===");
        LoadBalancer lb = new LoadBalancer(pool);
        lb.routeLeastConnections(new Request("next-req"));

        // PROBLEM 3: health check must verify CAN SERVE, not just alive.
        log.info("=== readiness health check ===");
        c.exhaustConnectionPool();                     // C is 'up' but cannot serve
        HealthChecker checker = new HealthChecker();
        for (AppInstance inst : pool) {
            boolean ready = checker.isReady(inst);
            log.info(() -> inst.name() + " live=" + inst.isAlive() + " ready=" + ready);
            if (!ready) lb.remove(inst);
        }
        lb.routeLeastConnections(new Request("after-health"));
    }
}

// ─── model/Request.java ───
class Request { final String id; Request(String id) { this.id = id; } }

// ─── instance/AppInstance.java ───
class AppInstance {
    private final String name;
    private final Set<String> localSessions = new HashSet<>(); // the BAD local state
    private int activeConnections = 0;
    private long loadMillis = 0;
    private boolean poolExhausted = false;
    AppInstance(String name) { this.name = name; }
    String name() { return name; }

    void localLogin(String customerId) { localSessions.add(customerId); }
    boolean hasLocalSession(String customerId) { return localSessions.contains(customerId); }

    void addWorkMillis(long ms) { loadMillis += ms; activeConnections++; }
    long loadMillis() { return loadMillis; }
    int activeConnections() { return activeConnections; }
    void incConnections() { activeConnections++; }

    boolean isAlive() { return true; }                 // process is up
    void exhaustConnectionPool() { poolExhausted = true; }
    // Readiness: can we actually get a DB connection and reach dependencies?
    boolean canGetDbConnection() { return !poolExhausted; }
}

// ─── session/SharedSessionStore.java (Redis stand-in — shared across instances) ───
class SharedSessionStore {
    private final Map<String, String> store = new HashMap<>();
    void put(String key, String json) { store.put(key, json); }
    String get(String key) { return store.get(key); }
}

// ─── lb/LoadBalancer.java ───
class LoadBalancer {
    private static final Logger log = Logger.getLogger("Scale");
    private final List<AppInstance> pool;
    LoadBalancer(List<AppInstance> pool) { this.pool = pool; }
    void remove(AppInstance inst) {
        pool.remove(inst);
        log.warning(() -> "Removed " + inst.name() + " from rotation (not ready)");
    }
    void routeLeastConnections(Request req) {
        AppInstance chosen = pool.get(0);
        for (AppInstance i : pool) if (i.activeConnections() < chosen.activeConnections()) chosen = i;
        chosen.incConnections();
        AppInstance f = chosen;
        log.info(() -> "Routed " + req.id + " → " + f.name()
                + " (active=" + f.activeConnections() + ", least loaded)");
    }
}

// ─── lb/HealthChecker.java (readiness, not just liveness) ───
class HealthChecker {
    boolean isReady(AppInstance inst) {
        // Alive is not enough; verify it can actually serve a request.
        return inst.isAlive() && inst.canGetDbConnection();
    }
}

// ─── config/BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
